/**
 * Floating comment card.
 * The global initializer is kept because comment providers load this file lazily.
 */
class Barrage {
    constructor(comments) {
        this.api = window.Solitude || {};
        this.dom = document.querySelector('.comment-barrage');
        this.barrageList = this.filterAndFlatten(comments);
        this.barrageIndex = 0;
        this.commentInterval = null;
        this.exitTimers = new Set();
        this.activeItem = null;
        this.hoverOnCommentBarrage = false;
        this.handleMouseEnter = () => { this.hoverOnCommentBarrage = true; };
        this.handleMouseLeave = () => { this.hoverOnCommentBarrage = false; };
        this.init();
    }

    filterAndFlatten(comments) {
        if (!Array.isArray(comments)) return [];
        return comments.flatMap(comment => {
            if (!comment || typeof comment !== 'object') return [];
            const replies = this.filterAndFlatten(comment.replies);
            return [comment, ...replies];
        });
    }

    sanitizeContent(content) {
        const template = document.createElement('template');
        template.innerHTML = String(content ?? '');
        return (template.content.textContent || '').replace(/\s+/g, ' ').trim();
    }

    getAvatar(comment) {
        const configuredAvatar = String(this.api.config?.comment?.avatar || '').replace(/\/$/, '');
        const avatar = String(comment.avatar || comment.mailId || '').trim();
        if (/^(https?:|data:|blob:)/i.test(avatar)) return avatar;
        const hash = String(comment.mailMd5 || avatar).trim();
        return hash && configuredAvatar
            ? `${configuredAvatar}/avatar/${encodeURIComponent(hash)}`
            : String(this.api.config?.lazyload?.error || '');
    }

    getCommentTarget(comment) {
        const target = String(comment.id || '').trim();
        return target || 'post-comment';
    }

    createActionButton(className, label, action, target, tag = 'button') {
        const button = document.createElement(tag);
        if (tag === 'button') button.type = 'button';
        else if (tag === 'a') button.href = target ? `#${encodeURIComponent(target)}` : 'javascript:void(0);';
        button.className = className;
        button.textContent = label;
        button.dataset.solitudeAction = action;
        button.dataset.solitudePrevent = 'true';
        if (target) button.dataset.solitudeTarget = target;
        return button;
    }

    createBarrageItem(comment) {
        const content = this.sanitizeContent(comment.content);
        if (!content) return false;

        const nick = String(comment.nick || '匿名用户').trim() || '匿名用户';
        const target = this.getCommentTarget(comment);
        const item = document.createElement('div');
        item.className = 'comment-barrage-item';

        const surface = document.createElement('div');
        surface.className = 'efu-dock-surface';

        const head = document.createElement('div');
        head.className = 'barrageHead';

        const user = document.createElement('div');
        user.className = 'barrageUser';

        const avatar = document.createElement('img');
        avatar.className = 'barrageAvatar';
        avatar.src = this.getAvatar(comment);
        avatar.alt = nick;
        avatar.loading = 'lazy';
        avatar.referrerPolicy = 'no-referrer';
        user.appendChild(avatar);

        const nickElement = document.createElement('span');
        nickElement.className = 'barrageNick';
        nickElement.textContent = nick;
        user.appendChild(nickElement);

        const actions = document.createElement('div');
        actions.className = 'barrageActions';
        actions.appendChild(this.createActionButton(
            'barrageTitle',
            this.api.config?.lang?.barrage?.title || '评论',
            'scrollTo',
            'post-comment',
            'a'
        ));

        const close = this.createActionButton(
            'comment-barrage-close',
            '',
            'switchCommentBarrage'
        );
        close.setAttribute('aria-label', '关闭热评');
        close.title = '关闭热评';
        const closeIcon = document.createElement('i');
        closeIcon.className = 'solitude fas fa-xmark';
        close.appendChild(closeIcon);
        actions.appendChild(close);

        head.append(user, actions);

        const contentLink = document.createElement('a');
        contentLink.className = 'barrageContent';
        contentLink.href = `#${encodeURIComponent(target)}`;
        contentLink.textContent = content;
        contentLink.dataset.solitudeAction = 'scrollTo';
        contentLink.dataset.solitudeTarget = target;
        contentLink.dataset.solitudePrevent = 'true';

        item.addEventListener('mouseenter', this.handleMouseEnter);
        item.addEventListener('mouseleave', this.handleMouseLeave);

        surface.append(head, contentLink);
        item.appendChild(surface);
        this.dom.appendChild(item);
        this.activeItem = item;
        return true;
    }

    removeBarrageItem(item) {
        if (!item) return;
        item.classList.add('out');
        const timer = setTimeout(() => {
            item.remove();
            this.exitTimers.delete(timer);
        }, 600);
        this.exitTimers.add(timer);
    }

    manageBarrage() {
        if (!this.barrageList.length || this.hoverOnCommentBarrage) return;

        const previous = this.activeItem;
        if (previous) this.removeBarrageItem(previous);
        this.activeItem = null;

        let attempts = 0;
        while (attempts < this.barrageList.length) {
            const comment = this.barrageList[this.barrageIndex];
            this.barrageIndex = (this.barrageIndex + 1) % this.barrageList.length;
            attempts += 1;
            if (this.createBarrageItem(comment)) break;
        }
    }

    initBarrage() {
        const savedState = this.api.saveToLocal?.get('commentBarrageSwitch');
        const isBarrageEnabled = savedState === undefined ? true : Boolean(savedState);
        this.dom.style.display = isBarrageEnabled ? 'flex' : 'none';
        this.dom.innerHTML = '';
        this.commentInterval = setInterval(() => this.manageBarrage(), 5000);
    }

    init() {
        if (!this.dom) return;
        this.initBarrage();
        this.api.onPageCleanup?.(() => this.destroy());
    }

    destroy() {
        if (this.commentInterval) clearInterval(this.commentInterval);
        this.commentInterval = null;
        this.exitTimers.forEach(timer => clearTimeout(timer));
        this.exitTimers.clear();
        this.dom?.replaceChildren();
        this.activeItem = null;
    }
}

function initializeCommentBarrage(comments) {
    window.currentBarrage?.destroy();
    window.currentBarrage = null;
    if (!Array.isArray(comments) || comments.length === 0) return;
    window.currentBarrage = new Barrage(comments);
}

window.initializeCommentBarrage = initializeCommentBarrage;
